column3:
if reclaim_isolates_what_this_root_references {
    allocator
        .isolate_the_slots_not_allocated_of_a_placement_referenced_by_an_abandoned_root(
            device,
            slot_to_isolate,
            SPAN_OF_ONE_SLOT,
        );
} else {
    allocator.isolate_abandoned(device, slot_to_isolate, SPAN_OF_ONE_SLOT);
}
